mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.4) * p.xz;
  p.yz = rot(time * 0.25) * p.yz;
  float scale = 1.0;
  for (int i = 0; i < 3; i++) {
    p = abs(p) - vec3(0.8, 0.8, 0.8);
    p.xy = rot(0.5) * p.xy;
    float k = 1.3 / dot(p, p);
    p *= k; scale *= k;
  }
  return (length(p) - 0.5) / scale;
}
